import{_ as t,o as r,c as s,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Test prolongé UIX sur tablette : 720 cartes","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/atlas/tablet-uix-dauertest.md","filePath":"fr/projects/atlas/tablet-uix-dauertest.md","lastUpdated":1793128957000}'),n={name:"fr/projects/atlas/tablet-uix-dauertest.md"};function i(o,e,l,u,c,p){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="test-prolonge-uix-sur-tablette-720-cartes" tabindex="-1">Test prolongé UIX sur tablette : 720 cartes <a class="header-anchor" href="#test-prolonge-uix-sur-tablette-720-cartes" aria-label="Permalink to &quot;Test prolongé UIX sur tablette : 720 cartes&quot;">​</a></h1><p>Au 19/10/2026. <strong>L’utilisateur confirme 60 minutes sur chaque hôte, .177 et .68, avec thèmes et reconnexion fonctionnels.</strong> App 0.1.327, HA 2026.10.2, UIX 8.4.0 ; Card-Mod n’est pas chargé. Appareil indiqué : Samsung Galaxy Tab A6, Android 11 / LineageOS, Chrome Mobile 155.</p><p>Sauvegardes complètes et captures des données avant préparation. Tableaux propres visibles dans la barre latérale sans Admin-only ; éditeurs, projets, plugins et réglages existants préservés.</p><p>Résultat fonctionnel rapporté par l’utilisateur, sans journaux JSON tablette collectés séparément, mesures FPS/mémoire ni résultats détaillés de rotation/ défilement. La vérification PC et la simulation locale restent distinctes.</p><h2 id="procedure-historique" tabindex="-1">Procédure historique <a class="header-anchor" href="#procedure-historique" aria-label="Permalink to &quot;Procédure historique&quot;">​</a></h2><p>Effectuer 60 minutes complètes par hôte, successivement :</p><p>Les vues propres <code>/atlas-tablet-uix-soak-20261019/720</code> sont retirées après le test ; les anciens liens ne sont plus actifs. Préparer de nouvelles sauvegardes et vues avant une future répétition.</p><ol><li>Brancher l’alimentation, garder l’écran éveillé et fermer les autres applications comme au test précédent. Garder la page au premier plan. Se connecter avec son compte HA existant sans partager les identifiants.</li><li>Vérifier « HA verbunden », puis appuyer une fois sur <strong>60 Minuten starten</strong>. Le compteur doit avancer ; ne pas recharger ni quitter la vue.</li><li>Toutes les dix minutes alterner portrait/paysage, défiler vers le bas et remonter. Observer blocages, chevauchements, textes coupés et cartes d’erreur. Textes, icônes et couleurs Mushroom suivent l’état synthétique.</li><li>Le contrôleur alterne 18/28 environ toutes les dix secondes, clair/sombre aux minutes 10/20/30/40/50 et reconnexion à 15/30/45. Une brève déconnexion est attendue, puis « HA verbunden » doit revenir sans rechargement.</li><li>À <strong>60 Minuten beendet</strong>, noter le résultat. <strong>Ergebnis markieren</strong> sélectionne le JSON local pour la copie normale. Si difficile sur tablette, indiquer d’abord hôte, durée finale, nombre de reconnexions et erreurs.</li><li>Répéter sur le second hôte. En cas de blocage ou déconnexion persistante, choisir <strong>Stoppen / Theme zurück</strong> et indiquer la durée avant le problème.</li></ol><p>Seuls des états synthétiques propres changent, aucun appareil réel. Les écarts du minuteur et temps de requête HA ne mesurent pas FPS/latence de rendu. Signaler veille ou arrière-plan comme interruption. Fin/arrêt restaure le thème initial. Recharger ne reprend pas automatiquement le test.</p><h2 id="cloture" tabindex="-1">Clôture <a class="header-anchor" href="#cloture" aria-label="Permalink to &quot;Clôture&quot;">​</a></h2><p>Tableaux, ressources, états synthétiques et UIX temporaire sont retirés ; fichiers WWW dans la corbeille récupérable File Studio. Sept projets et six plugins par hôte, 551 fichiers existants capturés sur .177 et neuf sur .68, réglages initiaux et anciennes entrées de corbeille restent inchangés. Trois sauvegardes complètes par hôte ; sauvegardes PC et mises à jour conservées. Ne jamais charger Card-Mod et UIX ensemble.</p>',11)])])}const h=t(n,[["render",i]]);export{m as __pageData,h as default};
